def longest_common_prefix_case_insensitive(strs):
    if not strs:
        return ""
    first = strs[0]
    count = 0
    for chars in zip(*[s.lower() for s in strs]):
        if len(set(chars)) == 1:
            count += 1
        else:
            break
    return first[:count]

