def min_swaps_to_sort(arr):
    values = list(arr)
    swaps = 0
    n = len(values)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if values[j] < values[min_idx]:
                min_idx = j
        if min_idx != i:
            values[i], values[min_idx] = values[min_idx], values[i]
            swaps += 1
    return swaps

def word_lengths(s):
    lengths = []
    current_len = 0
    in_word = False
    for ch in s:
        if ch.isspace():
            if in_word:
                lengths.append(current_len)
                in_word = False
                current_len = 0
        else:
            current_len += 1
            in_word = True
    if in_word:
        lengths.append(current_len)
    return lengths

