from itertools import groupby
from operator import itemgetter

def group_and_sort_by_key(records):
    result = {}
    ordered = sorted(records, key=itemgetter(0))
    for cat, group in groupby(ordered, key=itemgetter(0)):
        result[cat] = sorted(v for _, v in group)
    return result
